import { citypeList, saveAllCitype } from "@/api/system/ciModel";
import { Message } from 'element-ui'
import draggable from 'vuedraggable';

export default {
  components: {
    draggable
  },
  props: ['isShow'],
  data() {
    return{
      dragOptions: {
        animation: 150,
        scroll: true,
        group: 'description',
        disabled: false,
        ghostClass: 'ghost'
      },
      ciTypeList: [],
      saveLoading: false,
    }
  },
  mounted() {
    // console.log(draggable)
    this.getAllCitype()
  },
  methods: {
    // 获得全部层级
    getAllCitype() {
      citypeList().then(res => {
        this.ciTypeList = res.Return
      })
    },
    // 移除层级
    removeCiType(ciType) {
      this.$set(ciType, 'isDeleted', true);
    },
    // 恢复层级
    recoverCiType(ciType) {
      this.$set(ciType, 'isDeleted', null);
    },
    // 保存结果
    save() {
      this.saveLoading = true
      saveAllCitype({ciTypeList: this.ciTypeList}).then(res => {
        this.saveLoading = false
        Message({
          type: 'success',
          message: '保存成功!'
        })
        this.$emit("saveCitypeManage")
      }).catch(() => {
        this.saveLoading = false
      })
    }
  }
}
